--  Binary min-heap stored implicitly in an array.
--
--  The tree structure is not materialized: the children of the node stored at
--  index I are stored at 2 * I and 2 * I + 1, and its parent at I / 2. The
--  array slice 1 .. Last is therefore always a complete binary tree, and the
--  only structural property to maintain is that every node is smaller than or
--  equal to its children.
--
--  Verification level: see README.md.

package Heaps.Binary with SPARK_Mode is

   --  The capacity is bounded so that 2 * I never leaves the index range for
   --  any index I of a node that has children.

   Max_Capacity : constant := 2 ** 24;

   subtype Extended_Index is Natural range 0 .. Max_Capacity;
   subtype Index is Extended_Index range 1 .. Max_Capacity;

   type Key_Array is array (Index range <>) of Key_Type;

   type Heap (Capacity : Extended_Index) is record
      Last : Extended_Index := 0;
      Keys : Key_Array (1 .. Capacity);
   end record
     with Predicate => Last <= Capacity;
   --  A heap holds Last keys in Keys (1 .. Last). The slots beyond Last are
   --  irrelevant; they keep whatever value they last held.

   ---------------------------
   -- Structural properties --
   ---------------------------

   function Parent (I : Index) return Extended_Index is (I / 2)
     with Post => Parent'Result < I;
   --  Index of the parent of I, or 0 when I is the root

   function Is_Heap (H : Heap) return Boolean is
     (for all I in 2 .. H.Last => H.Keys (Parent (I)) <= H.Keys (I))
     with Ghost;
   --  The heap ordering: no node is smaller than its parent

   function Is_Minimum (H : Heap; K : Key_Type) return Boolean is
     (for all I in 1 .. H.Last => K <= H.Keys (I))
     with Ghost;
   --  K is a lower bound of every key currently stored in H

   ----------------
   -- Operations --
   ----------------

   function Size (H : Heap) return Extended_Index is (H.Last);

   function Is_Empty (H : Heap) return Boolean is (H.Last = 0);

   function Is_Full (H : Heap) return Boolean is (H.Last = H.Capacity);

   procedure Clear (H : in out Heap)
     with Post => Is_Empty (H) and then Is_Heap (H);

   function Peek_Min (H : Heap) return Key_Type is (H.Keys (1))
     with Pre => not Is_Empty (H);

   procedure Lemma_Root_Is_Minimum (H : Heap)
     with Ghost,
          Pre  => not Is_Empty (H) and then Is_Heap (H),
          Post => Is_Minimum (H, Peek_Min (H));
   --  The heap ordering only relates a node to its parent; that the root is a
   --  lower bound of the whole array follows by induction along the paths to
   --  the root, which is what this lemma establishes once and for all.

   procedure Insert (H : in out Heap; K : Key_Type)
     with Pre  => not Is_Full (H) and then Is_Heap (H),
          Post => Is_Heap (H) and then Size (H) = Size (H)'Old + 1;

   procedure Extract_Min (H : in out Heap; K : out Key_Type)
     with Pre  => not Is_Empty (H) and then Is_Heap (H),
          Post => Is_Heap (H)
                  and then Size (H) = Size (H)'Old - 1
                  and then K = Peek_Min (H)'Old
                  and then Is_Minimum (H'Old, K);

end Heaps.Binary;
EOF
cat > src/heaps-binary.adb <<'EOF'
package body Heaps.Binary with SPARK_Mode is

   ---------------------------
   -- Lemma_Root_Is_Minimum --
   ---------------------------

   procedure Lemma_Root_Is_Minimum (H : Heap) is
   begin
      --  Induction on the index: the parent of I is a smaller index, so by the
      --  time I is reached the root has already been shown to be below it.

      for I in 1 .. H.Last loop
         pragma Loop_Invariant
           (for all J in 1 .. I => H.Keys (1) <= H.Keys (J));
      end loop;
   end Lemma_Root_Is_Minimum;

   -----------
   -- Clear --
   -----------

   procedure Clear (H : in out Heap) is
   begin
      H.Last := 0;
   end Clear;

   ------------
   -- Insert --
   ------------

   procedure Insert (H : in out Heap; K : Key_Type) is
      Hole : Index := H.Last + 1;
      --  The new key conceptually sits in a hole that travels up towards the
      --  root as long as the parent is strictly greater. Moving the hole
      --  rather than swapping halves the number of writes: the key itself is
      --  only stored once, when its final position is known.
   begin
      H.Last := Hole;

      while Hole > 1 and then H.Keys (Parent (Hole)) > K loop
         H.Keys (Hole) := H.Keys (Parent (Hole));
         Hole := Parent (Hole);

         pragma Loop_Invariant (Hole <= H.Last);
         pragma Loop_Invariant (H.Last = H.Last'Loop_Entry);

         --  The heap ordering holds everywhere except at the hole, whose
         --  content is about to be overwritten.
         pragma Loop_Invariant
           (for all J in 2 .. H.Last =>
              (if J /= Hole then H.Keys (Parent (J)) <= H.Keys (J)));

         --  The parent of the hole still dominates the children of the hole,
         --  which is what keeps the ordering valid when the hole moves up.
         pragma Loop_Invariant
           (for all J in 2 .. H.Last =>
              (if Parent (J) = Hole and Hole > 1
               then H.Keys (Parent (Hole)) <= H.Keys (J)));

         --  The key being inserted fits in the hole as far as the children of
         --  the hole are concerned.
         pragma Loop_Invariant
           (for all J in 2 .. H.Last =>
              (if Parent (J) = Hole then K <= H.Keys (J)));

         pragma Loop_Variant (Decreases => Hole);
      end loop;

      H.Keys (Hole) := K;
   end Insert;

   -----------------
   -- Extract_Min --
   -----------------

   procedure Extract_Min (H : in out Heap; K : out Key_Type) is
      Moved : constant Key_Type := H.Keys (H.Last);
      --  The key of the last node, which has to be reinserted somewhere on
      --  the path from the root down

      Hole  : Index := 1;
      Child : Index;
   begin
      Lemma_Root_Is_Minimum (H);

      K := H.Keys (1);
      H.Last := H.Last - 1;

      loop
         exit when Hole > H.Last / 2;
         --  Past that point the hole is a leaf and the search is over

         --  Move down through the smaller of the two children
         Child := 2 * Hole;

         if Child < H.Last and then H.Keys (Child + 1) < H.Keys (Child) then
            Child := Child + 1;
         end if;

         pragma Assert
           (for all J in 2 .. H.Last =>
              (if Parent (J) = Hole then H.Keys (Child) <= H.Keys (J)));

         exit when H.Keys (Child) >= Moved;

         H.Keys (Hole) := H.Keys (Child);
         Hole := Child;

         pragma Loop_Invariant (Hole <= H.Last);
         pragma Loop_Invariant (H.Last = H.Last'Loop_Entry);

         --  The heap ordering holds everywhere except at the hole
         pragma Loop_Invariant
           (for all J in 2 .. H.Last =>
              (if J /= Hole then H.Keys (Parent (J)) <= H.Keys (J)));

         --  The parent of the hole dominates the children of the hole
         pragma Loop_Invariant
           (for all J in 2 .. H.Last =>
              (if Parent (J) = Hole and Hole > 1
               then H.Keys (Parent (Hole)) <= H.Keys (J)));

         --  The key being moved down is still large enough for the hole
         pragma Loop_Invariant
           (if Hole > 1 then H.Keys (Parent (Hole)) <= Moved);

         pragma Loop_Variant (Increases => Hole);
      end loop;

      if H.Last > 0 then
         H.Keys (Hole) := Moved;
      end if;
   end Extract_Min;

end Heaps.Binary;
